const fs = require('fs');
const { execSync } = require('child_process');
const path = '/workspace/testbed/docs/customer_report.docx';

// Use unzip to extract document.xml, then parse it
const tmp = '/tmp/docx_extract';
execSync('rm -rf ' + tmp + ' && mkdir -p ' + tmp);
execSync('cd ' + tmp + ' && unzip -o ' + path + ' word/document.xml 2>/dev/null');
const xml = fs.readFileSync(tmp + '/word/document.xml', 'utf-8');

// Extract text between <w:t> tags
const texts = [];
let currentPara = [];
// Split by paragraph markers
const paras = xml.split(/<w:p[ >]/);
for (const para of paras) {
    const tMatches = [...para.matchAll(/<w:t[^>]*>([^<]*)<\/w:t>/g)];
    const line = tMatches.map(m => m[1]).join('');
    texts.push(line);
}
console.log(texts.filter((_, i) => i > 0).join('\n'));
