const zlib = require('zlib');
const fs = require('fs');

const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Parse ZIP manually to find word/document.xml
let offset = 0;
const entries = [];
while (offset < buf.length - 4) {
    const sig = buf.readUInt32LE(offset);
    if (sig !== 0x04034b50) break; // local file header
    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const uncompSize = buf.readUInt32LE(offset + 22);
    const nameLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const name = buf.slice(offset + 30, offset + 30 + nameLen).toString('utf-8');
    const dataStart = offset + 30 + nameLen + extraLen;
    const data = buf.slice(dataStart, dataStart + compSize);
    entries.push({ name, compMethod, data, uncompSize });
    offset = dataStart + compSize;
}

const docEntry = entries.find(e => e.name === 'word/document.xml');
if (!docEntry) { console.log('No document.xml found. Files:', entries.map(e=>e.name)); process.exit(1); }

let xml;
if (docEntry.compMethod === 8) {
    xml = zlib.inflateRawSync(docEntry.data).toString('utf-8');
} else {
    xml = docEntry.data.toString('utf-8');
}

// Extract text
const paras = xml.split(/<\/w:p>/);
const lines = paras.map(p => {
    const tMatches = [...p.matchAll(/<w:t[^>]*>([^<]*)<\/w:t>/g)];
    return tMatches.map(m => m[1]).join('');
});
console.log(lines.join('\n').trim());
